* { box-sizing: border-box; }
html, body { margin: 0; font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif; background: #F9F9F9; }

.bandeja { width: 100%; box-sizing: border-box; }

/* Franja superior fija (no hace scroll con el contenido) — replica
 * Header.svelte/.topbar del dashboard original, sticky en la parte de
 * arriba del widget mientras el resto del contenido se desplaza. */
.topbar {
  position: sticky;
  top: 0;
  z-index: 10;
  background: #fff;
  border-bottom: 1px solid #E5E7EB;
  padding: 14px 26px;
}
.topbar__title { font-size: 17px; font-weight: 700; color: #1D2751; line-height: 1.2; }
.topbar__sub { margin-top: 2px; font-size: 12px; color: #4A5568; }

.bandeja__body { padding: 26px; }

.bandeja__kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 260px)); gap: 14px; margin-bottom: 22px; }

.kpi-card {
  background: #fff;
  border: 1px solid #E5E7EB;
  border-left: 4px solid transparent;
  border-radius: 14px;
  box-shadow: rgba(0,0,0,.1) 0px 1px 3px, rgba(0,0,0,.06) 0px 1px 2px;
  padding: 18px 20px;
}
.kpi-card--total { border-left-color: #1E5FA8; }
.kpi-card--alta { border-left-color: #F4880A; }

.kpi-card__value { font-size: 28px; font-weight: 700; line-height: 1; }
.kpi-card--total .kpi-card__value { color: #14327D; }
.kpi-card--alta .kpi-card__value { color: #E06A00; }
.kpi-card__label { margin-top: 4px; font-size: 10.5px; color: #4A5568; font-weight: 500; }

.bandeja__list-title { font-weight: 600; font-size: 13px; color: #1D2751; margin-bottom: 12px; }

.bandeja__list { display: flex; flex-direction: column; gap: 12px; }

.bandeja__empty { color: #4A5568; font-size: 12px; padding: 32px 0; text-align: center; }

.tarea-card {
  display: flex;
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 14px;
  box-shadow: rgba(0,0,0,.1) 0px 1px 3px, rgba(0,0,0,.06) 0px 1px 2px;
  overflow: hidden;
}

.tarea-card__body { flex: 1; padding: 16px 18px; min-width: 0; }

.tarea-card__tags { display: flex; align-items: center; gap: 8px; margin-bottom: 7px; flex-wrap: wrap; }

.tarea-card__tag {
  font-weight: 700;
  font-size: 8.5px;
  letter-spacing: .5px;
  color: #14327D;
  background: rgba(30,95,168,.1);
  padding: 3px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

.tarea-card__name { font-weight: 600; font-size: 14.5px; color: #1D2751; }

.tarea-card__caso { font-size: 10.5px; color: #9CA3AF; margin-top: 2px; }

.tarea-card__side {
  width: 190px;
  flex-shrink: 0;
  border-left: 1px solid #E5E7EB;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-end;
  gap: 12px;
}

.tarea-card__prioridad {
  font-size: 9.5px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
  background: #E8F0FE;
  color: #2557A7;
}
.tarea-card__prioridad--alta { background: #FCECEC; color: #D6202A; }

.tarea-card__btn {
  background: linear-gradient(90deg, #1E5FA8 0%, #2E7BD6 100%);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 8px 18px;
  font-family: inherit;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}
.tarea-card__btn:disabled { opacity: .4; cursor: not-allowed; }

.tarea-card__btn--ghost {
  background: #fff;
  color: #14327D;
  border: 1.5px solid #6FA3DC;
}

